icash_next_before_inventory:
CREATE OR REPLACE FUNCTION public.icash_next_before_inventory()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j public.icash_text_ai_jobs;t public.icash_automation_tickets;
begin
 perform pg_advisory_xact_lock(726341927);
 if exists(select 1 from public.icash_text_ai_settings c join public.icash_operation_rates r on r.id=c.rate_id and r.enabled and r.expires_at>now() where c.enabled)
 and exists(select 1 from public.icash_operating_budget where id=1 and enabled)
 and not exists(select 1 from public.icash_automation_tickets where kind='text_ai' and created_at>now()-interval '10 seconds') then
 select q.* into j from public.icash_text_ai_jobs q join public.icash_accounts a on a.id=q.account_id and not a.bot_paused join public.icash_text_threads th on th.id=q.thread_id and not th.paused and th.ai_mode<>'off'
 where q.next_attempt_at<=now() and (q.state='pending' or (q.state='issued' and q.updated_at<now()-interval '15 minutes')) order by q.created_at for update of q skip locked limit 1;
 if found then
 update public.icash_text_ai_jobs set state='issued',updated_at=now(),next_attempt_at=now()+interval '15 minutes' where id=j.id;
 insert into public.icash_automation_tickets(account_id,kind,text_ai_job_id) values(j.account_id,'text_ai',j.id) returning * into t;
 return jsonb_build_object('token',t.token);
 end if;end if;
 return public.icash_next_before_text_ai();
end $function$

icash_next_before_text_ai:
CREATE OR REPLACE FUNCTION public.icash_next_before_text_ai()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j public.icash_title_tasks;t public.icash_automation_tickets;
begin
 perform pg_advisory_xact_lock(726341927);
 if exists(select 1 from public.icash_title_followup_settings where id=1 and enabled)
 and not exists(select 1 from public.icash_automation_tickets where kind='title_followup' and created_at>now()-interval '1 minute') then
 select f.* into j from public.icash_title_tasks f
 join public.icash_accounts a on a.id=f.account_id and not a.bot_paused
 join public.icash_deal_files d on d.id=f.deal_id and d.account_id=f.account_id and d.stage in ('under_contract','buyer_selected','title_open','closing')
 where f.kind='follow_up' and f.state='scheduled' and f.due_date<=(now() at time zone 'America/Chicago')::date and f.email_retry_at<=now()
 and (f.email_state='waiting' or (f.email_state='issued' and f.updated_at<now()-interval '15 minutes'))
 order by f.email_retry_at,f.due_date for update of f skip locked limit 1;
 if found then
 update public.icash_title_tasks set email_state='issued',updated_at=now() where id=j.id;
 insert into public.icash_automation_tickets(account_id,kind,title_task_id) values(j.account_id,'title_followup',j.id) returning * into t;
 return jsonb_build_object('token',t.token);
 end if;end if;
 return public.icash_next_before_title_followup();
end $function$

icash_next_before_title_followup:
CREATE OR REPLACE FUNCTION public.icash_next_before_title_followup()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j public.icash_fulfillment_jobs;t public.icash_automation_tickets;
begin
 perform pg_advisory_xact_lock(726341927);
 perform public.icash_queue_fulfillment();
 -- Limit preparation tickets to one per minute globally so reconciliation/calls are not starved.
 if not exists(select 1 from public.icash_automation_tickets where kind='fulfillment' and created_at>now()-interval '1 minute') then
 select f.* into j from public.icash_fulfillment_jobs f join public.icash_accounts a on a.id=f.account_id and not a.bot_paused where f.state='ready' order by f.updated_at for update of f skip locked limit 1;
 if found then
 update public.icash_fulfillment_jobs set state='issued',updated_at=now() where id=j.id;
 insert into public.icash_automation_tickets(account_id,kind,fulfillment_job_id) values(j.account_id,'fulfillment',j.id) returning * into t;
 return jsonb_build_object('token',t.token);
 end if;end if;
 return public.icash_next_before_fulfillment();
end $function$

icash_next_outreach_channel:
CREATE OR REPLACE FUNCTION public.icash_next_outreach_channel()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare last_voice timestamptz;last_text timestamptz;ticket jsonb;
begin
 perform pg_advisory_xact_lock(726341927);
 -- Original-result reads release only receipt-verified work; no resend/redial.
 ticket:=public.icash_issue_due_signing_result();
 if ticket->>'token' is not null then return ticket;end if;
 ticket:=public.icash_issue_due_voice_result();
 if ticket->>'token' is not null then return ticket;end if;

 select last_dispatch_at into last_voice from public.icash_voice_scheduler where id=1;
 -- Existing (kind,created_at DESC) index keeps this read bounded.
 select created_at into last_text from public.icash_automation_tickets
 where kind='seller_opener' order by created_at desc limit 1;
 -- Give a waiting call its turn after a text. If either lane has no eligible
 -- work, the existing fallback continues through the other work immediately.
 if last_voice is null or last_text>last_voice then
  ticket:=public.icash_issue_ready_voice_ticket();
  if ticket->>'token' is not null then return ticket;end if;
 end if;
 return public.icash_next_before_unstarted_sms_recovery();
end $function$
